INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_mat-7-racionalni-cisla_0','Kolik je 1/2 + 1/2?',ARRAY['1/2','2','1/4','1']::TEXT[],3,'Dvě poloviny dají celek.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_1','Které číslo je větší?',ARRAY['0,005','-0,5','0,5','0,05']::TEXT[],2,'0,5 je pět desetin, ostatní jsou menší.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_2','Kolik je -3 + 5?',ARRAY['-8','2','8','-2']::TEXT[],1,'Od 5 odečteme 3.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_3','Kolik je 3/4 − 1/4?',ARRAY['1/2','3/8','1/4','3/2']::TEXT[],0,'2/4 = 1/2.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_4','Zapiš 0,25 zlomkem v základním tvaru.',ARRAY['2/5','25/10','1/4','1/5']::TEXT[],2,'0,25 = 25/100 = 1/4.',2,ARRAY[]::TEXT[],NULL,4,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_5','Kolik je (-2) · (-3)?',ARRAY['-6','-5','6','5']::TEXT[],2,'Záporné krát záporné je kladné.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_6','Kolik je 2/3 · 3/4?',ARRAY['1/2','5/7','1/3','6/12 jako 6']::TEXT[],0,'Čitatele i jmenovatele vynásobíme: 6/12 = 1/2.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_7','Kolik je (-12) : 4?',ARRAY['-8','-48','3','-3']::TEXT[],3,'Záporné dělené kladným je záporné.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_8','Kolik je 1/2 : 1/4?',ARRAY['2','1/2','1/8','4']::TEXT[],0,'Dělení = násobení převrácenou hodnotou: 1/2 · 4 = 2.',3,ARRAY[]::TEXT[],NULL,8,'c_mat-7-racionalni-cisla',NULL,NOW()),
('q_mat-7-racionalni-cisla_9','Seřaď od nejmenšího: 0,3; 1/4; 2/5.',ARRAY['2/5; 0,3; 1/4','1/4; 2/5; 0,3','0,3; 1/4; 2/5','1/4; 0,3; 2/5']::TEXT[],3,'1/4 = 0,25; 2/5 = 0,4.',4,ARRAY[]::TEXT[],NULL,9,'c_mat-7-racionalni-cisla',NULL,NOW()),
