('q_mat-7-racionalni-cisla_11','Jaká je opačná hodnota k číslu -7/3?',ARRAY['-7/3','3/7','-3/7','7/3']::TEXT[],3,'Opačné číslo má opačné znaménko.',4,ARRAY[]::TEXT[],NULL,11,'c_mat-7-racionalni-cisla',NULL,NOW()),
